import{_ as e,o as r,c as d,a0 as a}from"./chunks/framework.DScjKhBS.js";const m=JSON.parse('{"title":"Academy and LMS","description":"Twelve training and course repositories — AWS, AI, data science, and tutorials.","frontmatter":{"title":"Academy and LMS","description":"Twelve training and course repositories — AWS, AI, data science, and tutorials."},"headers":[],"relativePath":"reports/edi-repos-analysis/05-academy-lms.md","filePath":"reports/edi-repos-analysis/05-academy-lms.md"}'),o={name:"reports/edi-repos-analysis/05-academy-lms.md"};function s(n,t,i,c,l,g){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="academy-and-lms" tabindex="-1">Academy and LMS <a class="header-anchor" href="#academy-and-lms" aria-label="Permalink to &quot;Academy and LMS&quot;">​</a></h1><hr><h4 id="admin-academy-aws" tabindex="-1"><code>admin-academy-aws</code> <a class="header-anchor" href="#admin-academy-aws" aria-label="Permalink to &quot;`admin-academy-aws`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>iOLAP Academy 2023 AWS course solutions: IMDb ingest → S3/Glue → API Gateway Lambda</td></tr><tr><td><strong>Tech stack</strong></td><td>Python 3, AWS Lambda, Glue, DynamoDB, S3, Athena/SQL views, CloudFormation, CodeBuild</td></tr><tr><td><strong>Organization</strong></td><td><code>lambda/</code>, <code>glue/</code>, <code>sql/</code>, <code>dynamodb/</code>, <code>cicd/</code>, <code>s3/</code></td></tr><tr><td><strong>Coding style</strong></td><td>Script-style Python; config dicts; module docstrings with route docs</td></tr><tr><td><strong>CI/testing</strong></td><td><code>cicd/buildspec.yml</code> (mostly commented); no unit tests</td></tr><tr><td><strong>Advantages</strong></td><td>End-to-end data pipeline; documented AWS resource naming</td></tr><tr><td><strong>Disadvantages</strong></td><td>Hardcoded ARNs/buckets; <code>cdk/</code> empty; training-account coupling</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Naming conventions for multi-tenant resources. Lambda proxy response shape similar to WP REST.</td></tr></tbody></table><hr><h4 id="elixirr-academy-aws-academy-admin" tabindex="-1"><code>elixirr-academy-aws-academy-admin</code> <a class="header-anchor" href="#elixirr-academy-aws-academy-admin" aria-label="Permalink to &quot;`elixirr-academy-aws-academy-admin`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Academy admin infrastructure — IMDb dataset ingestion and API Gateway for course participants</td></tr><tr><td><strong>Tech stack</strong></td><td>AWS Glue, Lambda (awswrangler), API Gateway, S3, CloudFormation/CodePipeline, Python 3</td></tr><tr><td><strong>Organization</strong></td><td><code>resources/{glue,lambda,s3}/</code>; <code>cicd/</code>; <code>scripts/</code>, <code>docs/</code></td></tr><tr><td><strong>Coding style</strong></td><td>Functional Lambda handlers; env-var config with hardcoded fallbacks; module-level boto3 clients</td></tr><tr><td><strong>CI/testing</strong></td><td>CodePipeline on main push; no unit tests</td></tr><tr><td><strong>Advantages</strong></td><td>Complete admin-side data platform; partition-filtered API</td></tr><tr><td><strong>Disadvantages</strong></td><td>Hardcoded SNS ARNs/bucket names; DEBUG logging in prod paths</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>API Gateway Lambda proxy ≈ WP REST custom endpoints. CodePipeline deploy ≈ GitHub Actions → WP Engine deploy.</td></tr></tbody></table><hr><h4 id="elixirr-academy-course-aws" tabindex="-1"><code>elixirr-academy-course-aws</code> <a class="header-anchor" href="#elixirr-academy-course-aws" aria-label="Permalink to &quot;`elixirr-academy-course-aws`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Elixirr Academy AWS course — cloud ETL engine (DynamoDB config → Lambda extract → Glue transform → Redshift)</td></tr><tr><td><strong>Tech stack</strong></td><td>AWS Lambda, Glue, Step Functions, DynamoDB, S3, SNS, Athena/Redshift SQL, CloudFormation, Python</td></tr><tr><td><strong>Organization</strong></td><td><code>resources/{lambda,glue,dynamodb,s3,sql,statemachine}/</code>; <code>docs/md/Day 1–8</code>; <code>cicd/</code></td></tr><tr><td><strong>Coding style</strong></td><td>Script-style Lambda; global config dict; boto3 at module level</td></tr><tr><td><strong>CI/testing</strong></td><td>CodePipeline via CloudFormation; no unit tests</td></tr><tr><td><strong>Advantages</strong></td><td>End-to-end ETL narrative; day-by-day docs; event-driven architecture</td></tr><tr><td><strong>Disadvantages</strong></td><td>README/structure drift; hardcoded defaults; no automated tests</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Event-driven ETL ≈ WP cron + Action Scheduler hooks chaining import jobs. DynamoDB config ≈ WP options table for job state.</td></tr></tbody></table><hr><h4 id="elixirr-academy-course-ai" tabindex="-1"><code>elixirr-academy-course-ai</code> <a class="header-anchor" href="#elixirr-academy-course-ai" aria-label="Permalink to &quot;`elixirr-academy-course-ai`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Academy AI course solutions — LangChain, RAG, vector stores, multi-agent, Streamlit, MCP chatbot demo</td></tr><tr><td><strong>Tech stack</strong></td><td>Python, Jupyter, LangChain/LangGraph, Streamlit, ChromaDB, Azure Search, OpenAI, MCP SDK; ~270 pinned packages</td></tr><tr><td><strong>Organization</strong></td><td><code>notebooks/</code> (lessons 01–13); <code>data/</code> (large footprint); <code>MCP Example/</code></td></tr><tr><td><strong>Coding style</strong></td><td>Notebook-centric; mix of <code>.ipynb</code> and <code>.py</code>; deprecated notebooks retained</td></tr><tr><td><strong>CI/testing</strong></td><td>None; manual notebook execution</td></tr><tr><td><strong>Advantages</strong></td><td>Broad AI curriculum; working MCP example with architecture diagram</td></tr><tr><td><strong>Disadvantages</strong></td><td>Huge data footprint; incomplete README; no test automation</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>MCP server/client ≈ WP Abilities API or custom REST tool endpoints for AI agents.</td></tr></tbody></table><hr><h4 id="elixirr-academy-infra" tabindex="-1"><code>elixirr-academy-infra</code> <a class="header-anchor" href="#elixirr-academy-infra" aria-label="Permalink to &quot;`elixirr-academy-infra`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>AWS guardrails for Elixirr/iOLAP Academy accounts — scheduled resource scanning, SNS alerts, IAM provisioning, account teardown</td></tr><tr><td><strong>Tech stack</strong></td><td>AWS SAM, Python 3.11 Lambdas, Pipenv, boto3, CloudWatch alarms, SNS, DynamoDB/Glue/Lambda scanners</td></tr><tr><td><strong>Organization</strong></td><td><code>template.yaml</code>; <code>lambdas/</code>; <code>scripts/</code>; <code>account_nuke/</code></td></tr><tr><td><strong>Coding style</strong></td><td>Straightforward procedural Python; scanner classes with env-driven thresholds</td></tr><tr><td><strong>CI/testing</strong></td><td>Manual <code>sam build</code> / <code>sam deploy</code>; no pipeline or unit tests</td></tr><tr><td><strong>Advantages</strong></td><td>Clear operational purpose; parameterized limits; teardown scripts for academy lifecycle</td></tr><tr><td><strong>Disadvantages</strong></td><td>No automated tests; typo in SNS topic name; PowerShell nuke scripts Windows-centric</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>None directly</td></tr></tbody></table><hr><h4 id="elixirr-ai-academy-final-tasks-2025" tabindex="-1"><code>elixirr-ai-academy-final-tasks-2025</code> <a class="header-anchor" href="#elixirr-ai-academy-final-tasks-2025" aria-label="Permalink to &quot;`elixirr-ai-academy-final-tasks-2025`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Monorepo of three capstone AI projects from 2025 academy cohort</td></tr><tr><td><strong>Sub-projects</strong></td><td>Content curator (Streamlit, LangGraph, Bedrock); tech interviews assistant (Streamlit, DynamoDB, Textract); outreach system (partial)</td></tr><tr><td><strong>Coding style</strong></td><td>Streamlit-first, script-style Python; mixed maturity</td></tr><tr><td><strong>CI/testing</strong></td><td>None; committed build artifacts in outreach project</td></tr><tr><td><strong>Advantages</strong></td><td>Realistic AI use cases</td></tr><tr><td><strong>Disadvantages</strong></td><td>Inconsistent docs; invalid <code>requirements.txt</code> entries; no shared standards</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>None directly</td></tr></tbody></table><hr><h4 id="elixirr-ai-academy-final-tasks-2026-azure" tabindex="-1"><code>elixirr-ai-academy-final-tasks-2026-azure</code> <a class="header-anchor" href="#elixirr-ai-academy-final-tasks-2026-azure" aria-label="Permalink to &quot;`elixirr-ai-academy-final-tasks-2026-azure`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Four team capstone projects on Azure — AI agents, RAG, operational dashboards</td></tr><tr><td><strong>Sub-projects</strong></td><td>AirAware (FastAPI, Cosmos DB, LangGraph); FoodLens (Streamlit, Azure AI Search); NewsRisk (Azure Functions, LangGraph); RetailWeather (FastAPI, React, Cosmos DB)</td></tr><tr><td><strong>Coding style</strong></td><td>2026 cohort more structured — Pydantic models, repository pattern, router modules</td></tr><tr><td><strong>CI/testing</strong></td><td>RetailWeather has tests; others minimal</td></tr><tr><td><strong>Advantages</strong></td><td>RetailWeather is production-shaped (graceful degradation, API docs, env reference) — best academy architecture reference</td></tr><tr><td><strong>Disadvantages</strong></td><td>Placeholder READMEs on some teams; no shared CI pipeline</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>RetailWeather&#39;s separation of deterministic rules from LLM explanation — good pattern for WP AI features.</td></tr></tbody></table><hr><h4 id="ds-intro-code" tabindex="-1"><code>ds-intro-code</code> <a class="header-anchor" href="#ds-intro-code" aria-label="Permalink to &quot;`ds-intro-code`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>LMS companion for iOLAP Data Science Introduction — Jupyter notebooks aligned to Müller/Guido ML textbooks</td></tr><tr><td><strong>Tech stack</strong></td><td>Python 3, Jupyter, scikit-learn 0.24, pandas 1.3, matplotlib 3.3, numpy 1.19</td></tr><tr><td><strong>Organization</strong></td><td>Flat — 24 notebooks by chapter</td></tr><tr><td><strong>CI/testing</strong></td><td>None</td></tr><tr><td><strong>Advantages</strong></td><td>Clear pedagogical progression</td></tr><tr><td><strong>Disadvantages</strong></td><td>Stale dependency pins; no automated validation</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Shared helper modules ≈ theme <code>inc/</code> utilities. Environment setup docs ≈ Local WP + Composer onboarding.</td></tr></tbody></table><hr><h4 id="lms-react-course" tabindex="-1"><code>lms-react-course</code> <a class="header-anchor" href="#lms-react-course" aria-label="Permalink to &quot;`lms-react-course`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>React training course content (markdown lessons), not a runnable app</td></tr><tr><td><strong>Tech stack</strong></td><td>Markdown only</td></tr><tr><td><strong>CI/testing</strong></td><td>None</td></tr><tr><td><strong>Advantages</strong></td><td>Clear pedagogical intent for SPA concepts</td></tr><tr><td><strong>Disadvantages</strong></td><td>Essentially a stub; single lesson file</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>SPA vs server-rendered pages — directly relevant for headless WP vs traditional PHP theme rendering.</td></tr></tbody></table><hr><h4 id="lms-devops-kubernetes" tabindex="-1"><code>lms-devops-kubernetes</code> <a class="header-anchor" href="#lms-devops-kubernetes" aria-label="Permalink to &quot;`lms-devops-kubernetes`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>LMS course material for provisioning Kubernetes cluster on EC2 via Ansible</td></tr><tr><td><strong>Tech stack</strong></td><td>Ansible, Ubuntu 22.04, kubeadm, EC2</td></tr><tr><td><strong>CI/testing</strong></td><td>None; manual ansible-playbook execution</td></tr><tr><td><strong>Advantages</strong></td><td>Practical hands-on K8s bootstrap path</td></tr><tr><td><strong>Disadvantages</strong></td><td>Incomplete (TODO sections); stale EC2 hostnames in README</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>None directly</td></tr></tbody></table><hr><h4 id="hasura-web-api-tutorial" tabindex="-1"><code>hasura-web-api-tutorial</code> <a class="header-anchor" href="#hasura-web-api-tutorial" aria-label="Permalink to &quot;`hasura-web-api-tutorial`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Hands-on Hasura GraphQL tutorial with Express backend, Docker Compose, JWT (RS256)</td></tr><tr><td><strong>Tech stack</strong></td><td>Hasura GraphQL Engine v2.39, Postgres 15, Express/Node.js 20, Docker Compose</td></tr><tr><td><strong>Organization</strong></td><td><code>docker-compose.yml</code>; <code>hasura-tutorial-backend/</code>; <code>hasura-tutorial-completed/</code>; <code>queries/</code></td></tr><tr><td><strong>CI/testing</strong></td><td><code>npm test</code> stub; manual docker-compose</td></tr><tr><td><strong>Advantages</strong></td><td>Self-contained local stack; JWT auth pattern documented</td></tr><tr><td><strong>Disadvantages</strong></td><td>Committed keys/secrets (intentional for learning); no automated tests</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>JWT role-based access and GraphQL BFF patterns vs WP REST API — auth boundary design is transferable.</td></tr></tbody></table><hr><h4 id="arkit-tutorial" tabindex="-1"><code>ARKit-Tutorial</code> <a class="header-anchor" href="#arkit-tutorial" aria-label="Permalink to &quot;`ARKit-Tutorial`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Finished iOS ARKit tutorial — image tracking on Pokémon cards, overlay 3D models</td></tr><tr><td><strong>Tech stack</strong></td><td>Swift, UIKit, ARKit, SceneKit, Xcode</td></tr><tr><td><strong>CI/testing</strong></td><td>None</td></tr><tr><td><strong>Advantages</strong></td><td>Small, complete demo</td></tr><tr><td><strong>Disadvantages</strong></td><td>No tests, no modularization, storyboard-based</td></tr><tr><td><strong>WP/PHP transfer</strong></td><td>Minimal direct relevance</td></tr></tbody></table><hr>',38)])])}const u=e(o,[["render",s]]);export{m as __pageData,u as default};
